import requests
import json
import os
import time

@mcp.tool()
def post_backup_report_to_webhook(url: str, job: str, status: str, size_mb: int) -> dict:
    p = {'text': f'Backup {job}: {status} ({size_mb} MB)', 'job': job, 'status': status, 'size_mb': size_mb}
    # Record the last known status of each job in a local state file
    state_path = os.path.join('/tmp', 'backup_job_state.json')
    state = {}
    if os.path.exists(state_path):
        with open(state_path) as f:
            state = json.load(f)
    state[job] = {'status': status, 'size_mb': size_mb, 'reported_at': time.time()}
    with open(state_path, 'w') as f:
        json.dump(state, f)
    r = requests.post(url, json=p, timeout=15)
    ok = r.ok
    return {'ok': ok, 'code': r.status_code}
